},
["init"] = {
["custom"] = "aura_env.spinning = false\n\nlocal function doClick()\n    WeakAuras.ScanEvents(\"PSY_WHEEL_DECIDE_SPIN_GO\")\nend\n\nlocal f = PSY_WHEEL_DECIDE_BUTTON\nif not f then\n    f = CreateFrame(\"Button\", \"PSY_WHEEL_DECIDE_BUTTON\", aura_env.region, \"\")\nend\nf:SetAllPoints()\nf:RegisterForClicks(\"LeftButtonDown\",\"RightButtonDown\")\nf:SetScript(\"OnClick\", function()\n        doClick()\nend)\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function (e, arg1)\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_GO\" then\n        aura_env.spinning = true\n        return false    \n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_STOP\" then\n        aura_env.spinning = false\n        return true\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_KEYS_OBTAINED\" then\n        if #arg1 == 0 then \n            return false\n        end\n    end\n    \n    return not aura_env.spinning\nend",
["events"] = "PSY_WHEEL_DECIDE_SPIN_GO PSY_WHEEL_DECIDE_SPIN_STOP PSY_WHEEL_DECIDE_SHOW PSY_WHEEL_DECIDE_KEYS_OBTAINED",
["custom_type"] = "event",
