["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "\n\n",
["event"] = "Health",
["unit"] = "player",
["custom"] = "(function()\n    local forms = {\n      [102] = { form = 24858, icon = 136036 },\n      [103] = { form = 768, icon = 132115 },\n      [104] = { form = 5487, icon = 132276 },\n      [105] = { form = 0, icon = 136116  },\n    }\n    return function(s, event, ...)\n      local form = GetShapeshiftForm()\n      local specId = GetSpecializationInfo(GetSpecialization())\n      local show\n      if not forms[specId] then\n        show = false\n      elseif form == 3 then\n        show = false\n      elseif forms[specId].form == 0 then\n        show = form ~= 0 and form ~= 4\n      elseif form == 0 then\n        show = true\n      else\n        show = forms[specId].form ~= select(4, GetShapeshiftFormInfo(form))\n      end\n      local state = s[\"\"]\n      if not state then\n        if not show then return end\n        state = {}\n        s[\"\"] = state\n      end\n      state.changed = true\n      state.show = show\n      state.icon = forms[specId] and forms[specId].icon\n      return state.changed\n    end\nend)()",
["events"] = "PLAYER_TALENT_UPDATE,UPDATE_SHAPESHIFT_COOLDOWN,UPDATE_SHAPESHIFT_FORM",
