["check"] = "event",
["names"] = {
},
["custom"] = "(function()\n    local plates = {}\n    local pockets =  {}\n    return function(a,e,n,s)\n      if e == \"TRIGGER\" then\n        if n == 2 then\n          wipe(plates)\n          for unit in pairs(s or {}) do\n            if UnitGUID(unit) then\n              plates[UnitGUID(unit)] = unit\n            end\n          end\n        end\n        if n == 3 then\n          wipe(pockets)\n          for _, data in pairs(s or {}) do\n            pockets[data.destGUID] = data\n          end\n        end\n      end\n      \n      a:RemoveAll()\n      if InCombatLockdown() then return end\n      for guid in pairs(plates) do\n        if (not not pockets[guid]) == (aura_env.config.mode == 1) then\n          a:Update(guid, {\n              show = true,\n              unit = plates[guid]\n          })\n        end\n      end\n    end\nend)()",
