["custom"] = "function(states, ...)\n    local fac_id = 470\n    local fac_data = C_Reputation.GetFactionDataByID(fac_id)\n    \n    if fac_data then\n        local rep_total = 84000\n        local rep_curr = fac_data.currentStanding + 42000\n        \n        states[fac_id] = {\n            changed = true,\n            show = true,\n            progressType = \"static\",\n            value = rep_curr,\n            total = rep_total\n        }\n        \n        return true\n    end\n    \n    return false\nend\n",
