["Delve Speed Tracker (Auto Changes Daily Based on Story)"] = {
["outline"] = "OUTLINE",
["wagoID"] = "DAGg3PbVo",
["parent"] = "Delve Speed Tracker",
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "",
["shadowYOffset"] = -2,
["anchorPoint"] = "TOPLEFT",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["custom"] = "if aura_env.region and aura_env.region.cloneId then\n    aura_env.regionList[aura_env.region.cloneId] = {region = aura_env.region, state = aura_env.state}\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "if aura_env.region and aura_env.region.cloneId then\n    aura_env.regionList[aura_env.region.cloneId] = nil\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "if not aura_env then aura_env = {} end\n\n-- Initialize saved data table (automatically persists between sessions)\naura_env.saved = aura_env.saved or {}\n\n-- Region tracking (required for click handling)\naura_env.regionList = {}\n\n-- Persistent display state using aura_env.saved\nif not aura_env.displayState then\n    aura_env.displayState = aura_env.saved.displayState or \"expanded\"  -- \"expanded\", \"collapsed\", \"bountiful_only\"\nend\n\n-- Map ID to Atlas Icon mapping\naura_env.zoneIcons = {\n    [2248] = \"majorfactions_icons_storm512\",        -- Isle of Dorn\n    [2214] = \"majorfactions_icons_candle512\",       -- The Ringing Deeps\n    [2215] = \"talents-heroclass-paladin-lightsmith\", -- Hallowfall\n    [2255] = \"notoriety-32x32\",                     -- Azj-Kahet\n    [2371] = \"majorfactions_icons_stars512\",        -- Undermine (future)\n    [2346] = \"majorfactions_icons_ManaforgeVandals512\" -- K'aresh (future)\n}\n\n-- Delve configuration table - clean data only\naura_env.delves = {\n    -- Isle of Dorn (mapId: 2248)\n    [\"Kriegval's Rest\"] = {\n        mapId = 2248,\n        variants = {\n            [\"Swarming Kobolds\"] = \"B\",\n            [\"Lost Keepsakes\"] = \"B\", \n            [\"Dagran's Day Out\"] = \"B\",\n            [\"Corrupted Candles\"] = \"C\",\n            [\"Funny Candles\"] = \"B\"\n        }\n    },\n    [\"Fungal Folly\"] = {\n        mapId = 2248,\n        variants = {\n            [\"Spreading Decay\"] = \"B\",\n            [\"Lost Miners\"] = \"S\",\n            [\"Explorer's Competition\"] = \"A\",\n            [\"Oversparked Operation\"] = \"A\",\n            [\"Teleporter Tremors\"] = \"A\"\n        }\n    },\n    [\"Earthcrawl Mines\"] = {\n        mapId = 2248,\n        variants = {\n            [\"Precious Ores\"] = \"C\",\n            [\"Kidnapped Earthen\"] = \"C\",\n            [\"Fiery Grounds\"] = \"C\",\n            [\"Looking for Treasure\"] = \"B\",\n            [\"Bugs and Grubs\"] = \"B\"\n        }\n    },\n    \n    -- The Ringing Deeps (mapId: 2214)\n    [\"The Waterworks\"] = {\n        mapId = 2214,\n        variants = {\n            [\"Trust Issues\"] = \"B\",\n            [\"Captured Engineers\"] = \"B\",\n            [\"Stomping Some Sense\"] = \"B\",\n            [\"Put a Wrench on It\"] = \"B\"\n        }\n    },\n    [\"The Dread Pit\"] = {\n        mapId = 2214,\n        variants = {\n            [\"Smashing Skardyn\"] = \"B\",\n            [\"Lost Gems\"] = \"B\",\n            [\"Kobold Kidnapping\"] = \"B\",\n            [\"Darkfuse Disruption\"] = \"B\"\n        }\n    },\n    [\"Excavation Site 9\"] = {\n        mapId = 2214,\n        variants = {\n            [\"Lost Excavators\"] = \"A\",\n            [\"Black Blood Profits\"] = \"A\",\n            [\"Rowdy Rifts\"] = \"A\",\n            [\"A Knightly Quest\"] = \"A\",\n            [\"Culinary Catastrophe\"] = \"A\"\n        }\n    },\n    \n    -- Hallowfall (mapId: 2215)\n    [\"Nightfall Sanctum\"] = {\n        mapId = 2215,\n        variants = {\n            [\"Kyron's Assault\"] = \"C\",\n            [\"Dark Ritual\"] = \"C\",\n            [\"Signal Noise\"] = \"C\",\n            [\"Aiming to get Even\"] = \"C\"\n        }\n    },\n    [\"The Sinkhole\"] = {\n        mapId = 2215,\n        variants = {\n            [\"Raen's Gambit\"] = \"S\",\n            [\"Illusory Rescue\"] = \"A\",\n            [\"Lurking Terror\"] = \"S\",\n            [\"Orphan's Holiday\"] = \"A\"\n        }\n    },\n    [\"Skittering Breach\"] = {\n        mapId = 2215,\n        variants = {\n            [\"Renilash Beckons\"] = \"C\",\n            [\"Old Rituals\"] = \"C\",\n            [\"Shadow Realm\"] = \"C\",\n            [\"Relics of the Old Gods\"] = \"C\"\n        }\n    },\n    [\"Mycomancer Cavern\"] = {\n        mapId = 2215,\n        variants = {\n            [\"Missing Pigs\"] = \"B\",\n            [\"The Great Scavenger Hunt\"] = \"B\",\n            [\"Mushroom Morsel\"] = \"B\"\n        }\n    },\n    \n    -- Azj-Kahet (mapId: 2255)\n    [\"The Spiral Weave\"] = {\n        mapId = 2255,\n        variants = {\n            [\"From the Weaver with Love\"] = \"A\",\n            [\"Tortured Hostages\"] = \"A\",\n            [\"Strange Disturbances\"] = \"A\",\n            [\"Down to Size\"] = \"A\"\n        }\n    },\n    [\"Tak-Rethan Abyss\"] = {\n        mapId = 2255,\n        variants = {\n            [\"Niffen Napping\"] = \"S\",\n            [\"Goblin Mischief\"] = \"S\",\n            [\"Pheromone Fury\"] = \"S\",\n            [\"Pump the Brakes\"] = \"S\"\n        }\n    },\n    [\"The Underkeep\"] = {\n        mapId = 2255,\n        variants = {\n            [\"Weaver Rescue\"] = \"C\",\n            [\"Torture Victims\"] = \"C\",\n            [\"Evolved Research\"] = \"C\",\n            [\"Runaway Evolution\"] = \"C\",\n            [\"Third Party Operation\"] = \"C\"\n        }\n    },\n    \n    -- Future/Special zones\n    [\"Sidestreet Sluice\"] = {\n        mapId = 2371,\n        variants = {\n            [\"All That Glitters\"] = \"S\",\n            [\"Mr. DELVER\"] = \"S\",\n            [\"Teleporter Tantrums\"] = \"S\",\n            [\"Explosive Demolition\"] = \"S\",\n            [\"Crocolisk Reintroduction\"] = \"S\"\n        }\n    },\n    [\"Archival Assault\"] = {\n        mapId = 2346,\n        variants = {\n            [\"Relic Retrieval\"] = \"A\",\n            [\"Smash and Jab\"] = \"A\",\n            [\"Shadowed Wings\"] = \"A\",\n            [\"Waygate Wiles\"] = \"A\"\n        }\n    }\n}\n\n-- Difficulty configuration - single source of truth\naura_env.difficultyConfig = {\n    [\"S\"] = {\n        name = \"Turbo\",\n        time = \"< 10 min\",\n        color = \"|cff22C55E\",\n        priority = 1,\n        isEasy = true\n    },\n    [\"A\"] = {\n        name = \"Fast\", \n        time = \"10-12 min\",\n        color = \"|cff84CC16\",\n        priority = 2,\n        isEasy = false\n    },\n    [\"B\"] = {\n        name = \"Mid\",\n        time = \"12-15 min\", \n        color = \"|cffF97316\",\n        priority = 3,\n        isEasy = false\n    },\n    [\"C\"] = {\n        name = \"Slow\",\n        time = \"15-20 min\",\n        color = \"|cffEF4444\",\n        priority = 4,\n        isEasy = false\n    },\n    [\"D\"] = {\n        name = \"Very Slow\",\n        time = \"20+ min\",\n        color = \"|cff991B1B\",\n        priority = 5,\n        isEasy = false\n    }\n}\n\n-- Helper Functions (simplified)\nfunction aura_env.get_current_delve_variants()\n    local activeVariants = {}\n    local processedMaps = {}\n    \n    -- Safety check for delves table\n    if not aura_env.delves or type(aura_env.delves) ~= \"table\" then\n        return activeVariants\n    end\n    \n    -- Get unique map IDs from delves configuration\n    for _, delveInfo in pairs(aura_env.delves) do\n        if delveInfo and delveInfo.mapId and not processedMaps[delveInfo.mapId] then\n            processedMaps[delveInfo.mapId] = true\n            \n            local pois = C_AreaPoiInfo.GetDelvesForMap(delveInfo.mapId)\n            if pois and type(pois) == \"table\" then\n                for _, areaPoiID in ipairs(pois) do\n                    local poiInfo = C_AreaPoiInfo.GetAreaPOIInfo(delveInfo.mapId, areaPoiID)\n                    if poiInfo and (poiInfo.description:find(\"Delve\") or poiInfo.description:find(\"Bountiful\")) and poiInfo.tooltipWidgetSet then\n                        local widgets = C_UIWidgetManager.GetAllWidgetsBySetID(poiInfo.tooltipWidgetSet)\n                        if widgets and type(widgets) == \"table\" then\n                            for _, widget in pairs(widgets) do\n                                if widget and widget.widgetType == 8 and widget.widgetID then\n                                    local widgetInfo = C_UIWidgetManager.GetTextWithStateWidgetVisualizationInfo(widget.widgetID)\n                                    if widgetInfo and widgetInfo.text and widgetInfo.text:find(\"WHITE_FONT_COLOR:\") then\n                                        local variantName = widgetInfo.text:match(\"WHITE_FONT_COLOR:(.*)\")\n                                        if variantName then\n                                            local isBountiful = poiInfo.description:find(\"Bountiful\")\n                                            activeVariants[variantName] = isBountiful and \"bountiful\" or true\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    \n    return activeVariants\nend\n\nfunction aura_env.format_delve_entry(delveName, mapId)\n    local shortDelve = delveName:gsub(\"^The \", \"\"):gsub(\" Sanctum$\", \"\"):gsub(\" Cavern$\", \"\"):gsub(\" Mines$\", \"\")\n    local icon = aura_env.zoneIcons[mapId] or \"majorfactions_icons_candle512\"\n    return string.format(\"|A:%s:16:16:0:0|a |cffCBD5E1%s|r\", icon, shortDelve)\nend\n\nfunction aura_env.cycleDisplayState()\n    local states = {\"expanded\", \"collapsed\", \"bountiful_only\"}\n    for i, state in ipairs(states) do\n        if aura_env.displayState == state then\n            aura_env.displayState = states[i % #states + 1]\n            -- Save to persistent storage\n            aura_env.saved.displayState = aura_env.displayState\n            break\n        end\n    end\nend\n\nfunction aura_env.getDisplayStateIndicator()\n    local indicators = {\n        expanded = \"|A:common-button-collapseExpand-down:20:20:0:0|a\",\n        collapsed = \"|A:common-button-collapseExpand-up:20:20:0:0|a\",\n        bountiful_only = \"|A:StreamCinematic-PlayButton:20:20:0:0|a\"\n    }\n    return indicators[aura_env.displayState] or \"\"\nend\n\nfunction aura_env.getCategoryDisplayName(difficulty)\n    local config = aura_env.difficultyConfig[difficulty]\n    if config then\n        return string.format(\"%s%s (%s)|r\", config.color, config.name, config.time)\n    end\n    return \"Unknown\"\nend\n\n-- Main TSU function (simplified and optimized)\nfunction aura_env.UpdateDelveStates(allstates)\n    if not allstates or type(allstates) ~= \"table\" then\n        return false\n    end\n    \n    local activeVariants = aura_env.get_current_delve_variants()\n    local activeDelves = {}\n    \n    -- Build active delves list\n    for delveName, delveInfo in pairs(aura_env.delves) do\n        for variantName, difficulty in pairs(delveInfo.variants) do\n            if activeVariants[variantName] then\n                local config = aura_env.difficultyConfig[difficulty]\n                local isBountiful = activeVariants[variantName] == \"bountiful\"\n                if config then\n                    table.insert(activeDelves, {\n                            delveName = delveName,\n                            variantName = variantName,\n                            difficulty = difficulty,\n                            priority = config.priority,\n                            isEasy = config.isEasy,\n                            timeEst = config.time,\n                            mapId = delveInfo.mapId,\n                            displayName = isBountiful and \n                            string.format(\"|A:%s:16:16:0:0|a |cffFFD700%s|r |A:delves-bountiful:16:16:0:0|a\", aura_env.zoneIcons[delveInfo.mapId] or \"majorfactions_icons_candle512\", delveName:gsub(\"^The \", \"\"):gsub(\" Sanctum$\", \"\"):gsub(\" Cavern$\", \"\"):gsub(\" Mines$\", \"\")) or\n                            aura_env.format_delve_entry(delveName, delveInfo.mapId),\n                            tooltip = string.format(\"%s%s\\n%s\\nDifficulty: %s Tier\\nEstimated Time: %s\", \n                            delveName, isBountiful and \" (Bountiful)\" or \"\", variantName, difficulty, config.time),\n                            isBountiful = isBountiful\n                    })\n                end\n                break\n            end\n        end\n    end\n    \n    -- Create header\n    allstates[\"Header\"] = {\n        show = true,\n        changed = true,\n        progressType = \"static\",\n        value = 1,\n        total = 1,\n        name = \"|cff7DD3FC\" .. \"DELVE DIFFICULTY RANKINGS\" .. \"|r \" .. aura_env.getDisplayStateIndicator(),\n        yOffset = 0,\n        autoHide = false,\n        justify = \"LEFT\",\n        index = 0\n    }\n    \n    -- Clear existing states\n    for k in pairs(allstates) do\n        if k ~= \"Header\" then\n            allstates[k] = {show = false, changed = true}\n        end\n    end\n    \n    -- Handle collapsed state\n    if aura_env.displayState == \"collapsed\" then\n        return true\n    end\n    \n    -- Filter for bountiful_only mode\n    if aura_env.displayState == \"bountiful_only\" then\n        local filteredDelves = {}\n        for _, delve in ipairs(activeDelves) do\n            if delve.isBountiful then\n                table.insert(filteredDelves, delve)\n            end\n        end\n        activeDelves = filteredDelves\n    end\n    \n    -- Sort by priority (easier delves first)\n    table.sort(activeDelves, function(a, b)\n            return a.priority < b.priority\n    end)\n    \n    -- Group by difficulty and create display\n    local yOffset = 48 -- Start after header and spacer\n    local currentDifficulty = nil\n    \n    for _, delve in ipairs(activeDelves) do\n        -- Add tier header if difficulty changed\n        if currentDifficulty ~= delve.difficulty then\n            currentDifficulty = delve.difficulty\n            \n            -- Add spacer before tier (except first)\n            if yOffset > 48 then\n                yOffset = yOffset + 12\n            end\n            \n            -- Tier header\n            allstates[\"tier_\" .. delve.difficulty] = {\n                show = true,\n                changed = true,\n                progressType = \"static\",\n                value = 1,\n                total = 1,\n                name = aura_env.getCategoryDisplayName(delve.difficulty),\n                yOffset = yOffset,\n                autoHide = false,\n                justify = \"LEFT\",\n                index = yOffset\n            }\n            yOffset = yOffset + 24\n        end\n        \n        -- Create delve entry\n        allstates[delve.delveName] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = 6 - delve.priority, -- Higher value = easier delve\n            total = 5,\n            name = delve.displayName,\n            yOffset = yOffset,\n            autoHide = false,\n            justify = \"LEFT\",\n            index = yOffset,\n            \n            -- Custom fields\n            delveName = delve.delveName,\n            storyName = delve.variantName,\n            difficulty = delve.difficulty,\n            timeEstimate = delve.timeEst,\n            tooltip = delve.tooltip\n        }\n        yOffset = yOffset + 24\n    end\n    \n    return true\nend",
["do_custom"] = true,
},
