["custom"] = "function(allstates, event, ...)\n    if event == \"STATUS\" or event == \"OPTIONS\" then\n        return aura_env.UpdateDelveStates(allstates)\n    elseif event == \"GLOBAL_MOUSE_DOWN\" then\n        local button = select(1, ...)\n        if button == \"LeftButton\" then\n            for _, v in pairs(aura_env.regionList) do  \n                if v.region and MouseIsOver(v.region) and v.state then\n                    if v.state.name and string.find(v.state.name, \"DELVE DIFFICULTY RANKINGS\") then\n                        aura_env.cycleDisplayState()\n                        return aura_env.UpdateDelveStates(allstates)\n                    end\n                    break\n                end\n            end\n        end\n    else\n        if InCombatLockdown() then\n            return false\n        end\n        return aura_env.UpdateDelveStates(allstates)\n    end\n    return false\nend",
