["sparkOffsetX"] = 0,
["wagoID"] = "HlIKhWG0f",
["parent"] = "CorePower",
["customText"] = "function()\n    local stagger\n    if BrewmasterTools then \n        stagger = BrewmasterTools.GetNextTick()\n    else\n        stagger = UnitStagger('player')\n    end\n    if aura_env.config and aura_env.config.tickAbsolute then\n        return AbbreviateNumbers(stagger)\n    else\n        return (\"%0.1f\"):format(100 * stagger/UnitHealthMax('player')), \"%\"\n    end\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["customTextUpdate"] = "update",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["customVariables"] = "{\n  value = true,\n  total = true,\n  staggertick = {\n    display = \"Stagger Tick\",\n    type = \"number\",\n  },\n  staggertickpercent = {\n    display = \"Stagger Tick Percent\",\n    type = \"number\"\n  }\n}\n\n\n\n",
["custom_type"] = "stateupdate",
["names"] = {
},
["spellIds"] = {
},
["event"] = "Health",
["unit"] = "player",
["customDuration"] = "function()\n    \n    if not BrewmasterTools then return UnitStagger'player', UnitHealthMax'player', true end\n        \n        return UnitStagger'player', BrewmasterTools.GetNormalStagger(), true\n        \n        \n        \n    end",
["custom"] = "(function() \n    \n    local baseState = {\n      show = true,\n      progressType = \"static\",\n      value = 0,\n      total = 1,\n      staggertick = 0,\n      staggertickpercent = 0,\n    }\n    local function mutate(states, field, value)\n      if not states[\"\"] then states[\"\"] = CreateFromMixins(baseState) end\n      local mutated = states[\"\"][field] ~= value\n      if mutated then states[\"\"].changed = true end\n      states[\"\"][field] = value\n      return mutated\n    end\n    \n    local bucketLife = 10\n    local bucketTotal = 0\n    local livingBuckets = 0\n    local latestBucket = nil\n    local magic = {}\n    local function createBucket(amount, start, duration)\n      local bucket = {\n        start = start or GetTime(),\n        amount = amount,\n      }\n      livingBuckets = livingBuckets + 1\n      C_Timer.After(duration or bucketLife, function()\n          livingBuckets = livingBuckets - 1\n          bucketTotal = bucketTotal - bucket.amount\n          WeakAuras.ScanEvents(\"NORMALIZED_STAGGER_DEADBUCKET\", magic)\n      end)\n      return bucket\n    end\n    \n    local function addToBucket(amount)\n      local now = GetTime()\n      if livingBuckets == 0 then\n        for i = 1, bucketLife - 1 do\n          createBucket(amount, now - i, bucketLife - i)\n        end\n        bucketTotal = bucketTotal + amount * (bucketLife - 1)\n      end\n      if not latestBucket or (latestBucket.start + aura_env.config.bucketSize) < now then\n        latestBucket = createBucket(0, now)\n      end\n      latestBucket.amount = latestBucket.amount + amount\n      bucketTotal = bucketTotal + amount\n    end\n    local handler = {\n      COMBAT_LOG_EVENT_UNFILTERED = function(states, _, _, _, _, _, _, _, destGUID, _, _, _, ...)\n        \n        -- we're looking for events where the player absorbed damage with stagger\n        if destGUID ~= UnitGUID'player' then return end\n        \n        local absorbingSpellId, _, _, absorbAmount = select(type((...)) == \"number\" and 8 or 5, ...)\n        if absorbingSpellId ~= 115069 then return end -- absorbing spell was not stagger\n        addToBucket(absorbAmount)\n        return mutate(states, \"total\", bucketTotal)\n      end,\n      UNIT_MAXHEALTH = function(states)\n        return mutate(states, \"staggertickpercent\", 100 * states[\"\"].staggertick / (UnitHealthMax'player' > 0 and UnitHealthMax'player' or 1))\n      end,\n      TRIGGER = function (states, triggernum, otherstates)\n        if triggernum == 2 then\n          -- stagger debuff state changed\n          local staggerTick = otherstates and otherstates[\"\"] and otherstates[\"\"][\"points\"] and otherstates[\"\"][\"points\"][1] or 0\n          local mutated = mutate(states, \"staggertick\", staggerTick)\n          mutated = mutate(states, \"staggertickpercent\", 100 * staggerTick / (UnitHealthMax'player' > 0 and UnitHealthMax'player' or 1)) or mutated\n          return mutated\n        elseif triggernum == 3 then\n          -- stagger amt changed\n          return mutate(states, \"value\", otherstates[\"\"] and otherstates[\"\"].value)\n        elseif triggernum == 4 then\n          -- stagger duration changed\n          bucketLife = otherstates and otherstates[\"\"] and otherstates[\"\"].show and 13 or 10\n          return false\n        end\n      end,\n      NORMALIZED_STAGGER_DEADBUCKET = function(states, test)\n        if test ~= magic then return end\n        \n        return mutate(states, \"total\", bucketTotal)\n      end\n    }\n    \n    return function(states, event, ...)\n      if handler[event] then return handler[event](states, ...) end\n    end\nend)()",
["events"] = "CLEU:SPELL_ABSORBED UNIT_MAXHEALTH:player TRIGGER:2:3:4:5 NORMALIZED_STAGGER_UPDATE",
