["actions"] = {
["start"] = {
["do_custom"] = false,
["do_message"] = false,
["custom"] = "if not aura_env.state then return end\n\nif aura_env.state.raidMarkIndex then\n    aura_env.markersInUse[aura_env.state.raidMarkIndex] = UnitGUID(aura_env.state.unit)\nelse    \n    for i = 1, #aura_env.markersToUse do\n        if aura_env.markersToUse[i] and not aura_env.markersInUse[i] then\n            SetRaidTarget(aura_env.state.unit, i)\n            aura_env.markersInUse[i] = UnitGUID(aura_env.state.unit)\n            break\n        end\n    end\nend    \n\n\n\n",
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.markersToUse = {\n    false, --star\n    false, --orange\n    false, --purple\n    true,  --green\n    false, --moon\n    false, --blue\n    false, --cross\n    false, --skull\n}\n\naura_env.markersInUse = {}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["npcId"] = "223724",
["use_destFlags2"] = true,
["use_absorbMode"] = true,
["names"] = {
},
["destFlags2"] = "Hostile",
["debuffType"] = "HELPFUL",
["type"] = "unit",
["use_absorbHealMode"] = true,
["subeventSuffix"] = "_INTERRUPT",
["subeventPrefix"] = "SPELL",
["event"] = "Unit Characteristics",
["use_sourceFlags2"] = true,
["use_npcId"] = true,
["sourceFlags2"] = "Friendly",
["spellIds"] = {
},
["use_sourceUnit"] = false,
["use_unit"] = true,
["use_sourceFlags"] = false,
["unit"] = "nameplate",
["sourceFlags"] = "InGroup",
},
["untrigger"] = {
},
},
{
["trigger"] = {
["type"] = "custom",
["custom"] = "function(e,...)\n    if e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _,_,_,_,_,_,_,destGUID = ...\n        \n        for i, g in pairs(aura_env.markersInUse) do\n            if destGUID == g then\n                aura_env.markersInUse[i] = nil\n            end\n        end\n        \n    elseif e == \"TRIGGER\" then\n        local _, s = ...\n        \n        for _, v in pairs(s) do\n            if v.unit and v.raidMarkIndex then\n                local GUID = UnitGUID(v.unit)\n                \n                if aura_env.markersToUse[v.raidMarkIndex] then\n                    aura_env.markersInUse[v.raidMarkIndex] = GUID\n                else\n                    for i, g in pairs(aura_env.markersInUse) do\n                        if g == GUID then\n                            aura_env.markersInUse[i] = nil                            \n                            break\n                        end\n                    end\n                    \n                    for i = 1, #aura_env.markersToUse do\n                        if aura_env.markersToUse[i] and not aura_env.markersInUse[i] then\n                            SetRaidTarget(v.unit, i)\n                          --  aura_env.markersInUse[i] = GUID\n                            break\n                        end\n                    end\n                end \n            end   \n        end\n    end\nend\n\n\n",
["custom_type"] = "event",
["debuffType"] = "HELPFUL",
["events"] = "CLEU:UNIT_DIED:UNIT_DESTROYED:UNIT_DISSIPATES, TRIGGER:1",
["unit"] = "player",
