["Nameplate"] = {
["outline"] = "OUTLINE",
["wagoID"] = "P81wqCkkf",
["parent"] = "🌀 Legion Remix - Versa % Display",
["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function()\n  local text = aura_env.state.tooltip\n  if not text then return \"-\" end\n  \n  for line in text:gmatch(\"[^\\r\\n]+\") do\n    if line:match(\"Versatility\")\n    or line:match(\"Vielseitigkeit\")\n    or line:match(\"Polyvalence\")\n    or line:match(\"Versatilidad\")\n    or line:match(\"Универсальность\")\n    or line:match(\"Versatilità\")\n    or line:match(\"Versatilidade\")\n    or line:match(aura_env.config.text)\n    then\n      local num = line:match(\"([%d%,%.%^]+)\")\n      if not num then return \"-\" end\n      num = num:gsub(\",\", \".\"):gsub(\"%^\", \"\")\n      num = tonumber(num)\n      if not num then return \"-\" end\n      \n      if num >= 999 then\n        for l in text:gmatch(\"[^\\r\\n]+\") do\n          if l:match(\"Stamina\")\n          or l:match(\"Ausdauer\")\n          or l:match(\"Endurance\")\n          or l:match(\"Aguante\")\n          or l:match(\"Выносливость\")\n          or l:match(\"Tempra\")\n          or l:match(\"Vigor\")\n          then\n            if not l:find(\"%%\") then\n              local s = l:match(\"([%d%.,]+)\")\n              if s then\n                s = s:gsub(\",\", \".\") .. \"M\"\n                return \"|cFFFF4C4C\" .. s .. \"|r\"\n              end\n            end\n          end\n        end\n        return \"|cFFFF4C4C-|r\"\n      end\n      \n      local color\n      if num >= 900 then\n        color = \"|cFFFF4C4C\"\n      elseif num >= 700 then\n        color = \"|cFFFFB347\"\n      elseif num >= 500 then\n        color = \"|cFFB266FF\"\n      elseif num >= 200 then\n        color = \"|cFF66B2FF\"\n      elseif num >= 100 then\n        color = \"|cFF66FF66\"\n      else\n        color = \"|cFFFFFFFF\"\n      end\n      \n      return string.format(\"%s%d|r\", color, num)\n    end\n  end\nend",
