["shadowXOffset"] = 1,
["customAnchor"] = "-- Custom Anchor: Zeigt Text über dem Kopf der Mouseover-Einheit\nfunction()\n    local unit = \"mouseover\"\n    if not UnitExists(unit) then\n        return nil\n    end\n\n    -- Falls Nameplate vorhanden, daran anheften (beste Methode)\n    local plate = C_NamePlate.GetNamePlateForUnit(unit)\n    if plate and plate.UnitFrame and plate.UnitFrame.name then\n        return plate.UnitFrame.name\n    end\n\n    -- Wenn kein Nameplate (z. B. gegnerische Fraktion in neutraler Zone)\n    -- dann erstellen wir ein temporäres WorldFrame, das sich an der 3D-Position orientiert.\n    if not aura_env.worldAnchor then\n        local f = CreateFrame(\"Frame\", nil, UIParent)\n        f:SetSize(1, 1)\n        f:SetFrameStrata(\"HIGH\")\n\n        f:SetScript(\"OnUpdate\", function(self)\n            local u = self.unit\n            if not u or not UnitExists(u) then\n                self:Hide()\n                return\n            end\n            local x, y, z = UnitPosition(u)\n            if not x then\n                self:Hide()\n                return\n            end\n\n            local success, sx, sy = pcall(function()\n                return WorldToScreen(x, y, z + 2.2)\n            end)\n\n            if success and sx and sy then\n                self:ClearAllPoints()\n                self:SetPoint(\"CENTER\", UIParent, \"BOTTOMLEFT\", sx, sy)\n                self:Show()\n            else\n                self:Hide()\n            end\n        end)\n\n        aura_env.worldAnchor = f\n    end\n\n    aura_env.worldAnchor.unit = unit\n    aura_env.worldAnchor:Show()\n    return aura_env.worldAnchor\nend\n",
