["KWD - Controller - Keystone Obtainer"] = {
["wagoID"] = "xzvpUDanJ",
["authorOptions"] = {
},
["preferToUpdate"] = false,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["url"] = "https://wago.io/xzvpUDanJ/8",
["actions"] = {
["start"] = {
["custom"] = "WeakAuras.ScanEvents(\"PSY_DKEYS_SHOW\") ",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "WeakAuras.ScanEvents(\"PSY_DKEYS_HIDE\") ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.visible = false\n\naura_env.getData = function()\n    local keys = {}\n    local openRaidLib = LibStub:GetLibrary(\"LibOpenRaid-1.0\")\n    if openRaidLib then\n        local keystoneData = openRaidLib.GetAllKeystonesInfo()\n        if keystoneData then\n            table.sort(keystoneData, function (t1, t2) return t1.level > t2.level end)\n            \n            \n            local i = 0\n            for unitName, keystoneInfo in pairs(keystoneData) do\n                local mapName = C_ChallengeMode.GetMapUIInfo(keystoneInfo.mythicPlusMapID) or \"\"\n                \n                if \n                (UnitInParty(unitName) or unitName == UnitName(\"player\")) and \n                keystoneInfo.level > 0 then\n                    i = i + 1\n                    keys[i] = aura_env.createKey(i, unitName, mapName, keystoneInfo.level)\n                end\n            end\n        end\n    end\n    return keys\nend\n\n\naura_env.createKey = function(id, player, keystone, difficulty) \n    local keystoneAbr = aura_env.abreviateKeyName(keystone)\n    local keystoneFull = aura_env.adjustKeyName(keystone)\n    return {\n        show = true,\n        changed = true,\n        autoHide = false,\n        progressType = \"static\",\n        name = \"keystone\"..id,\n        icon = 525134,\n        index = id,\n        player = ({strsplit(\"-\", player)})[1],\n        keystone = keystoneAbr,\n        keystoneFull = keystoneFull,\n        difficulty = difficulty,\n        tooltip = keystoneFull .. \" +\" .. difficulty\n    }\nend\n\naura_env.getManualAbrvs = function() \n    return {\n        [\"Dawn of the Infinite: Galakrond's Fall\"] = \"FALL\",\n        [\"Dawn of the Infinite: Murozond's Rise\"] = \"RISE\",   \n        [\"Uldaman: Legacy of Tyr\"] = \"ULD\",\n        [\"Neltharus\"] = \"NELT\",\n        [\"Algeth'ar Academy\"] = \"AA\",\n    }\nend\n\naura_env.abreviateKeyName = function(keystone)\n    local manual = aura_env.getManualAbrvs()[keystone]\n    if manual ~= nil then return manual end\n    \n    local keyname = string.gsub(keystone, \"%'\", \" \")\n    local replaced = \"\"\n    for i, word in pairs ({strsplit(\" \",keyname)}) do \n        if i == 1 and word == \"The\" then\n            replace = replaced\n        else\n            replaced = replaced .. string.sub(word, 1, 1) \n        end\n    end\n    return string.upper(replaced)\nend\n\naura_env.adjustKeyName = function(keystone)\n    local keystoneFull = keystone\n    keystoneFull =    string.gsub(keystoneFull, \"Dawn of the Infinite\", \"DOTI\")\n    return keystoneFull\nend",
["do_custom"] = true,
},
},
["triggers"] = {
