["names"] = {
},
["custom"] = "function (e, arg1)\n    if e == \"PSY_WHEEL_DECIDE_SHOW\" then \n        aura_env.visible = true\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_HIDE\" then\n        aura_env.visible = false\n    end\n    \n    if aura_env.visible then   \n        if e == \"CHAT_MSG_ADDON\" and arg1 == \"LRS\" then\n            local keys = aura_env.getData()\n            WeakAuras.ScanEvents(\"PSY_WHEEL_DECIDE_KEYS_OBTAINED\", keys)\n        end\n    end\nend",
