{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["unit"] = "player",
["events"] = "PLAYER_SOFT_INTERACT_CHANGED",
["custom_hide"] = "timed",
["check"] = "event",
["custom"] = "(function() \n    local base = { show = true }\n    local function clear(states)\n      if not states[\"\"] then return end\n      states[\"\"].show = false\n      states[\"\"].changed = true\n      return true\n    end\n    \n    local function mutate(states, key, value)\n      local mutated = false\n      if not states[\"\"] then\n        mutated = true\n        states[\"\"] = CreateFromMixins(base)\n      end\n      mutated = mutated or states[\"\"][key] ~= value\n      states[\"\"][key] = value\n      states[\"\"].changed = mutated\n      return mutated\n    end\n    \n    \n    return function(states)\n      \n      local guid = UnitGUID(\"softinteract\")\n      if not guid or not guid:match(\"^GameObject\") then return clear(states) end\n      local objectID = tonumber((select(6, strsplit(\"-\", guid))))\n      if not objectID or not aura_env.nodes[objectID] then return clear(states) end\n      return mutate(states, \"show\", true)\n    end \nend)()",
["debuffType"] = "HELPFUL",
["customVariables"] = "(function() \n    local base = { show = true }\n    local function clear(states)\n      if not states[\"\"] then return end\n      states[\"\"].show = false\n      states[\"\"].changed = true\n      return true\n    end\n    \n    local function mutate(states, key, value)\n      local mutated = false\n      if not states[\"\"] then\n        mutated = true\n        states[\"\"] = CreateFromMixins(base)\n      end\n      mutated = mutated or states[\"\"][key] ~= value\n      states[\"\"][key] = value\n      states[\"\"].changed = mutated\n      return mutated\n    end\n    \n    \n    return function(states)\n      \n      local guid = UnitGUID(\"softinteract\")\n      if not guid or not guid:match(\"^GameObject\") then return clear(states) end\n      local objectID = tonumber((select(6, strsplit(\"-\", guid))))\n      if not objectID or not aura_env.nodes[objectID] then return clear(states) end\n      return mutate(states, \"show\", true)\n    end \nend)()\n\n\n\n",
},
