["icon_side"] = "LEFT",
["customText"] = "function()\n    local fac_id = 909\n    local fac_data = C_Reputation.GetFactionDataByID(fac_id)\n    \n    local rep_lvls = {\n        [1] = \"Hated\",\n        [2] = \"Hostile\",\n        [3] = \"Unfriendly\",\n        [4] = \"Neutral\",\n        [5] = \"Friendly\",\n        [6] = \"Honored\",\n        [7] = \"Revered\",\n        [8] = \"Exalted\"\n    }\n    \n    if fac_data then\n        local rep_total = 84000\n        local rep_curr = fac_data.currentStanding + 42000\n        \n        -- Set the bar color if necessary.\n        if aura_env.config[\"color_single\"] then\n            if aura_env.config[\"color_int\"] then\n                local function interpolate_color(color_start, color_end, t)\n                    -- Clamp t between 0 and 1\n                    if t < 0 then t = 0 end\n                    if t > 1 then t = 1 end\n                    \n                    -- Interpolate between the start and end colors\n                    local r = color_start.r + (color_end.r - color_start.r) * t\n                    local g = color_start.g + (color_end.g - color_start.g) * t\n                    local b = color_start.b + (color_end.b - color_start.b) * t\n                    local a = color_start.a + (color_end.a - color_start.a) * t\n                    \n                    return {r = r, g = g, b = b, a = a}\n                end\n                \n                local color_start = {r = 204.0 / 255.0, g = 77.0 / 255.0, b = 56.0 / 255.0, a = 1.0}\n                local color_end = {r = 0.0 / 255.0, g = 153.0 / 255.0, b = 26.0 / 255.0, a = 1.0}\n                local rep_pct = rep_curr / rep_total\n                local color_int = interpolate_color(color_start, color_end, rep_pct)\n                \n                aura_env.region.bar:SetForegroundColor(color_int.r, color_int.g, color_int.b, color_int.a)\n            else\n                if fac_data.reaction == 1 or fac_data.reaction == 2 then\n                    aura_env.region.bar:SetForegroundColor(204.0 / 255.0, 77.0 / 255.0, 56.0 / 255.0, 1.0)\n                elseif fac_data.reaction == 3 then\n                    aura_env.region.bar:SetForegroundColor(191.0 / 255.0, 69.0 / 255.0, 0.0 / 255.0, 1.0)\n                elseif fac_data.reaction == 4 then\n                    aura_env.region.bar:SetForegroundColor(230.0 / 255.0, 179.0 / 255.0, 0.0 / 255.0, 1.0)\n                else\n                    aura_env.region.bar:SetForegroundColor(0.0 / 255.0, 153.0 / 255.0, 26.0 / 255.0, 1.0)\n                end\n            end\n        end\n        \n        local rep_fmt_num = aura_env.config[\"rep_fmt\"]\n        local bar_str\n\n        if rep_fmt_num == 5 then\n            -- To maintain compliance with ElvUI's behavior, check if any text should be displayed first.\n            bar_str = \"\"\n        elseif rep_curr == rep_total then\n            -- If max reputation has been reached, don't show the reputation numbers.\n            bar_str = string.format(\n                \"%s: [%s]\",\n                fac_data.name,\n                rep_lvls[fac_data.reaction])\n        else\n            if rep_fmt_num == 1 then\n                -- Current\n                bar_str = string.format(\n                    \"%s: %d [%s]\",\n                    fac_data.name,\n                    rep_curr,\n                    rep_lvls[fac_data.reaction])\n            elseif rep_fmt_num == 2 then\n                -- Current - Max\n                bar_str = string.format(\n                    \"%s: %d - %d [%s]\",\n                    fac_data.name,\n                    rep_curr,\n                    rep_total,\n                    rep_lvls[fac_data.reaction])\n            elseif rep_fmt_num == 3 then\n                -- Current - Percent\n                bar_str = string.format(\n                    \"%s: %d - %d%% [%s]\",\n                    fac_data.name,\n                    rep_curr,\n                    math.floor((rep_curr / rep_total) * 100),\n                    rep_lvls[fac_data.reaction])\n            elseif rep_fmt_num == 4 then\n                -- Current - Percent (Remaining)\n                bar_str = string.format(\n                    \"%s: %d - %d%% (%d) [%s]\",\n                    fac_data.name,\n                    rep_curr,\n                    math.floor((rep_curr / rep_total) * 100),\n                    rep_total - rep_curr,\n                    rep_lvls[fac_data.reaction])\n            elseif rep_fmt_num == 4 then\n                -- Current - Remaining\n                bar_str = string.format(\n                    \"%s: %d - %d [%s]\",\n                    fac_data.name,\n                    rep_curr,\n                    rep_total - rep_curr,\n                    rep_lvls[fac_data.reaction])\n            elseif rep_fmt_num == 6 then\n                -- Percent\n                bar_str = string.format(\n                    \"%s: %d%% [%s]\",\n                    fac_data.name,\n                    math.floor((rep_curr / rep_total) * 100),\n                    rep_lvls[fac_data.reaction])\n            elseif rep_fmt_num == 7 then\n                -- Remaining\n                bar_str = string.format(\n                    \"%s: %d [%s]\",\n                    fac_data.name,\n                    rep_total - rep_curr,\n                    rep_lvls[fac_data.reaction])\n            end\n        end\n        \n        return bar_str\n    end\n    \n    return \"\"\nend",
