["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "-- ZONES --\nlocal ISLE_OF_DORN = 'Isle of Dorn'\nlocal RINGING_DEEP = 'The Ringing Deeps'\nlocal HALLOWFALL = 'Hallowfall'\nlocal AZJ_KAHET = 'Azj-Kahet'\n\n-- ZONE ID's --\nlocal ZONE_IDS = {\n    [2248] = ISLE_OF_DORN,\n    [2339] = ISLE_OF_DORN, -- Dornogal\n    [2214] = RINGING_DEEP,\n    [2215] = HALLOWFALL,\n    [2255] = AZJ_KAHET, \n    [2213] = AZJ_KAHET, -- City of Threads Umbral Bazaar\n    [2256] = AZJ_KAHET -- Twitching Gorge\n}\n\n-- POOLS --\nlocal GLIMMERPOOL = 'Glimmerpool'\nlocal BLOOD_IN_THE_WATER = 'Blood in the Water'\nlocal BLOODY_PERCH_SWARM = 'Bloody Perch Swarm'\nlocal CALM_SURFACING_RIPPLE = 'Calm Surfacing Ripple'\nlocal FESTERING_ROTPOOL = 'Festering Rotpool'\nlocal SWARM_OF_SLUM_SHARKS = 'Swam of Slum Sharks'\nlocal INFUSED_ICHOR_SPILL = 'Infused Ichor Spill'\nlocal RIVER_BASS_POOL = 'River Bass Pool'\nlocal ANGLERSEEKER_TORRENT = 'Anglerseeker Torrent'\nlocal STARGAZER_SWARM = 'Stargazer Swarm'\nlocal AZJ_KAHET_WATER = 'Azj-Kahet Water'\nlocal ALL_POOLS = 'All Pools'\nlocal ROYAL_RIPPLE = 'Royal Ripple'\nlocal ANY_WATER = 'Any Water'\n\nlocal ZONE_POOLS = {\n    [ISLE_OF_DORN] = {GLIMMERPOOL, CALM_SURFACING_RIPPLE, RIVER_BASS_POOL, BLOODY_PERCH_SWARM, FESTERING_ROTPOOL, STARGAZER_SWARM, ALL_POOLS},\n    [RINGING_DEEP] = {GLIMMERPOOL, CALM_SURFACING_RIPPLE, RIVER_BASS_POOL, ANGLERSEEKER_TORRENT, ALL_POOLS},\n    [HALLOWFALL] = {GLIMMERPOOL, CALM_SURFACING_RIPPLE, BLOODY_PERCH_SWARM, BLOOD_IN_THE_WATER, SWARM_OF_SLUM_SHARKS, INFUSED_ICHOR_SPILL, ANGLERSEEKER_TORRENT, ROYAL_RIPPLE, ALL_POOLS},\n    [AZJ_KAHET] = {GLIMMERPOOL, CALM_SURFACING_RIPPLE, SWARM_OF_SLUM_SHARKS, INFUSED_ICHOR_SPILL, ROYAL_RIPPLE, AZJ_KAHET_WATER, ALL_POOLS}\n}\n\naura_env.fish = {\n    {name = 'Arathor Hammerfish', questId=82928, zones={HALLOWFALL}, pools={BLOOD_IN_THE_WATER}, notes='', caught = false},\n    {name = 'Awoken Coelacanth', questId=82936, zones={AZJ_KAHET}, pools={AZJ_KAHET_WATER}, notes='Throw 10 Whispering Stargazer in water for 5 min buff', caught = false},\n    {name = 'Bismuth Bitterling', questId=82920, zones={ISLE_OF_DORN, RINGING_DEEP}, pools={GLIMMERPOOL}, notes='', caught = false},\n    {name = 'Bloody Perch', questId=82918, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL}, pools={BLOOD_IN_THE_WATER, BLOODY_PERCH_SWARM, CALM_SURFACING_RIPPLE, FESTERING_ROTPOOL, SWARM_OF_SLUM_SHARKS}, notes='', caught = false},\n    {name = 'Crystalline Sturgeon', questId=82919, zones={ISLE_OF_DORN, RINGING_DEEP}, pools={GLIMMERPOOL}, notes='', caught = false},\n    {name = 'Cursed Ghoulfish', questId=82935, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL, AZJ_KAHET}, pools={ALL_POOLS}, notes='', caught = false},\n    {name = 'Dilly-Dally Dace', questId=82947, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL}, pools={BLOOD_IN_THE_WATER, CALM_SURFACING_RIPPLE, FESTERING_ROTPOOL}, notes='', caught = false},\n    {name = 'Dornish Pike', questId=82926, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL}, pools={CALM_SURFACING_RIPPLE}, notes='', caught = false},\n    {name = 'Goldengill Trout', questId=82923, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL, AZJ_KAHET}, pools={FESTERING_ROTPOOL, GLIMMERPOOL, INFUSED_ICHOR_SPILL}, notes='', caught = false},\n    {name = 'Kaheti Slum Shark', questId=82930, zones={HALLOWFALL, AZJ_KAHET}, pools={BLOOD_IN_THE_WATER, SWARM_OF_SLUM_SHARKS}, notes='', caught = false},\n    {name = 'Nibbling Minnow', questId=82921, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL, AZJ_KAHET}, pools={CALM_SURFACING_RIPPLE}, notes='', caught = false},\n    {name = 'Pale Huskfish', questId=82931, zones={AZJ_KAHET, ISLE_OF_DORN}, pools={FESTERING_ROTPOOL, INFUSED_ICHOR_SPILL}, notes='', caught = false},\n    {name = 'Queen\\'s Lurefish', questId=82934, zones={HALLOWFALL, AZJ_KAHET}, pools={ROYAL_RIPPLE, ANY_WATER}, notes='Throw Regal Dottyback in water for buff, easier time than pool', caught = false},\n    {name = 'Quiet River Bass', questId=82925, zones={ISLE_OF_DORN, RINGING_DEEP}, pools={CALM_SURFACING_RIPPLE, RIVER_BASS_POOL}, notes='', caught = false},\n    {name = 'Regal Dottyback', questId=82929, zones={HALLOWFALL, AZJ_KAHET}, pools={ROYAL_RIPPLE}, notes='', caught = false},\n    {name = 'Roaring Anglerseeker', questId=82927, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL, AZJ_KAHET}, pools={ANGLERSEEKER_TORRENT}, notes='', caught = false},\n    {name = 'Sanguine Dogfish', questId=82932, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL, AZJ_KAHET}, pools={BLOOD_IN_THE_WATER, BLOODY_PERCH_SWARM}, notes='Bloody Perch buff increases chance to catch this fish', caught = false},\n    {name = 'Specular Rainbowfish', questId=82924, zones={ISLE_OF_DORN, RINGING_DEEP}, pools={GLIMMERPOOL}, notes='Use Specular Rainbowfish Lure for increased chance', caught = false},\n    {name = 'Spiked Sea Raven', questId=82933, zones={ISLE_OF_DORN, HALLOWFALL}, pools={ANGLERSEEKER_TORRENT, CALM_SURFACING_RIPPLE, GLIMMERPOOL, STARGAZER_SWARM}, notes='', caught = false},\n    {name = 'Whispering Stargazer', questId=82922, zones={ISLE_OF_DORN, RINGING_DEEP, HALLOWFALL}, pools={STARGAZER_SWARM}, notes='', caught = false}\n}\n\naura_env.update_display = function()\n    local text = 'Weekly Derby Dash Fish Tracker\\n\\n'\n    local zones = {}\n    local currentZoneID = C_Map.GetBestMapForUnit(\"player\")\n    local currentZone = ZONE_IDS[currentZoneID] or 'Unknown Zone'\n    \n    -- Organize fish by zone and pool\n    for _, fish in ipairs(aura_env.fish) do\n        fish.caught = C_QuestLog.IsQuestFlaggedCompleted(fish.questId)\n        \n        if fish.zones then\n            for _, zone in ipairs(fish.zones) do\n                if not zones[zone] then\n                    zones[zone] = {pools = {}, allCaught = true}\n                end\n                \n                if fish.pools then\n                    for _, pool in ipairs(fish.pools) do\n                        if not zones[zone].pools[pool] then\n                            zones[zone].pools[pool] = {}\n                        end\n                        \n                        table.insert(zones[zone].pools[pool], fish)\n                    end\n                end\n                \n                if not fish.caught then\n                    zones[zone].allCaught = false\n                end\n            end\n        end\n    end\n    \n    -- Build the output text\n    for zone, data in pairs(zones) do\n        if zone == currentZone then\n            text = text .. '\\n' .. WrapTextInColorCode(zone, 'ffffff00') .. '\\n'\n            \n            for pool, fishes in pairs(data.pools) do\n                -- Only display pool if there are uncaught fish\n                if ZONE_POOLS[zone] and tContains(ZONE_POOLS[zone], pool) then\n                    local hasUncaughtFish = false\n                    \n                    for _, fish in ipairs(fishes) do\n                        if not fish.caught then\n                            hasUncaughtFish = true\n                            break\n                        end\n                    end\n                    \n                    if hasUncaughtFish then\n                        text = text .. '    ' .. WrapTextInColorCode(pool, 'ffffff00') .. '\\n'\n                        \n                        for _, fish in ipairs(fishes) do\n                            if not fish.caught then\n                                text = text .. '        ' .. fish.name\n                                \n                                if fish.notes and fish.notes ~= '' then\n                                    text = text .. ' (' .. fish.notes .. ')'\n                                end\n                                \n                                text = text .. '\\n'\n                            end\n                        end\n                    end\n                end\n            end\n            \n            text = text .. '\\n'\n        else\n            local zoneStatus = data.allCaught and WrapTextInColorCode('DONE', 'ff00ff00') or WrapTextInColorCode('MISSING FISH', 'ffff0000')\n            \n            text = text .. WrapTextInColorCode(zone .. ' - ', 'ffffff00') .. zoneStatus .. '\\n'\n        end\n    end\n    \n    return text\nend\n\naura_env.text = aura_env.update_display()",
["do_custom"] = true,
},
